import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    parent = list(range(n))

    def find(a):
        while parent[a] != a:
            parent[a] = parent[parent[a]]
            a = parent[a]
        return a

    rows = {}
    cols = {}
    comps = n
    for i in range(n):
        x, y = int(data[1 + 2 * i]), int(data[2 + 2 * i])
        for d, key in ((rows, x), (cols, y)):
            if key in d:
                a, b = find(i), find(d[key])
                if a != b:
                    parent[a] = b
                    comps -= 1
            else:
                d[key] = i
    print(n - comps)

