import sys
from functools import lru_cache

data = sys.stdin.read().split()
n = int(data[0])
P = [(int(data[1 + 2 * i]), int(data[2 + 2 * i])) for i in range(n)]

@lru_cache(maxsize=None)
def f(mask):
    best = 0
    for i in range(n):
        if not (mask >> i) & 1:
            continue
        ok = False
        for j in range(n):
            if j != i and (mask >> j) & 1 and (P[j][0] == P[i][0] or P[j][1] == P[i][1]):
                ok = True
                break
        if ok:
            best = max(best, 1 + f(mask & ~(1 << i)))
    return best

print(f((1 << n) - 1))

